"""PC-side tests for Wiegand Raw. Needs gcc and Python 3. No Flipper needed.

    python3 test/run_tests.py

1. Formatting and decoding (wiegand_format.c) are checked against values this
   script works out independently, with its own bit arithmetic.
2. The capture logic (wiegand_capture.c) is run against simulated D0/D1 edges.

These do NOT test the screens, the SD card code, or anything electrical.
"""
import os
import random
import subprocess
import sys
import tempfile

HERE = os.path.dirname(os.path.abspath(__file__))
ROOT = os.path.dirname(HERE)
CFLAGS = ["-std=gnu11", "-Wall", "-Wextra", "-Werror", "-O1", "-fsanitize=address,undefined"]

failures = 0
checks = 0


def check(name, got, want):
    global failures, checks
    checks += 1
    if got != want:
        failures += 1
        print(f"FAIL {name}\n   got:  {got!r}\n   want: {want!r}")


def build(out, sources, extra=()):
    cmd = ["gcc", *CFLAGS, *extra, "-o", out, *sources]
    subprocess.run(cmd, check=True)


def run_driver(driver, bits):
    result = subprocess.run([driver, bits], capture_output=True, text=True)
    if result.returncode != 0:
        raise RuntimeError(f"driver failed for {bits!r}: rc={result.returncode} {result.stderr}")
    fields = {}
    text = result.stdout
    for key in ("PLAIN", "GROUPED", "HEXR", "HEXL", "DECODE", "KNOWN"):
        start = text.index(key + "<") + len(key) + 1
        end = text.index(">\n", start)
        fields[key] = text[start:end]
    return fields


# ---- independent reference implementations ---------------------------------

def ref_hex_right(bits):
    width = (len(bits) + 3) // 4
    return format(int(bits, 2), "X").zfill(width)


def ref_hex_left(bits):
    padded = bits + "0" * ((4 - len(bits) % 4) % 4)
    return format(int(padded, 2), "X").zfill(len(padded) // 4)


def ref_grouped(bits):
    # Nibbles counted from the right, 16 bits per line.
    lines = []
    rest = bits
    while rest:
        lines.insert(0, rest[-16:])
        rest = rest[:-16]
    out = []
    for line in lines:
        groups = []
        while line:
            groups.insert(0, line[-4:])
            line = line[:-4]
        out.append(" ".join(groups))
    return "\n".join(out)


def to_bits(value, width):
    return format(value, "b").zfill(width)


def even_parity_bit(payload):
    """Bit that makes the count of ones (payload + bit) even."""
    return str(payload.count("1") % 2)


def odd_parity_bit(payload):
    """Bit that makes the count of ones (payload + bit) odd."""
    return str((payload.count("1") + 1) % 2)


def flip(bits, index):
    return bits[:index] + ("1" if bits[index] == "0" else "0") + bits[index + 1:]


def h10301(fc, cn):
    body = to_bits(fc, 8) + to_bits(cn, 16)
    return even_parity_bit(body[:12]) + body + odd_parity_bit(body[12:])


def h10306(fc, cn):
    body = to_bits(fc, 16) + to_bits(cn, 16)
    return even_parity_bit(body[:16]) + body + odd_parity_bit(body[16:])


def h10304(fc, cn):
    body = to_bits(fc, 16) + to_bits(cn, 19)  # 35 data bits
    # Leading even parity covers the first 18 data bits, trailing odd parity
    # covers the last 18 data bits.
    return even_parity_bit(body[:18]) + body + odd_parity_bit(body[17:])


def keyscan36(oem, fc, cn):
    body = to_bits(oem, 10) + to_bits(fc, 8) + to_bits(cn, 16)  # 34 data bits
    return even_parity_bit(body[:17]) + body + odd_parity_bit(body[17:])


def mask_positions(n, mid_mask, lo_mask):
    """Indexes (0 = first bit received) selected by a Proxmark-style mask pair."""
    mask = (mid_mask << 32) | lo_mask
    return [n - 1 - r for r in range(n) if (mask >> r) & 1]


def corp1000(n, cc_bits, cn_bits, cc, cn, even_mid, odd_mid, all_mid):
    """Build a Corporate 1000 frame from the parity masks, one bit at a time."""
    bits = ["0"] * n
    bits[2:2 + cc_bits] = to_bits(cc, cc_bits)
    bits[2 + cc_bits:2 + cc_bits + cn_bits] = to_bits(cn, cn_bits)
    ones = lambda idx: sum(bits[i] == "1" for i in idx)
    # Second bit: even parity over its mask.
    bits[1] = str(ones(mask_positions(n, even_mid, 0xB6DB6DB6)) % 2)
    # Last bit: odd parity over its mask (the mask never includes the last bit).
    bits[n - 1] = str((ones(mask_positions(n, odd_mid, 0x6DB6DB6C)) + 1) % 2)
    # First bit: odd parity over every other bit.
    bits[0] = str((ones(range(1, n)) + 1) % 2)
    return "".join(bits)


def corp1000_35(cc, cn):
    return corp1000(35, 12, 20, cc, cn, 0x1, 0x3, 0x3)


def corp1000_48(cc, cn):
    return corp1000(48, 22, 23, cc, cn, 0x1B6D, 0x36DB, 0x7FFF)


def run_rfid(rfid, bits):
    result = subprocess.run([rfid, bits], capture_output=True, text=True)
    if result.returncode != 0:
        raise RuntimeError(f"rfid driver failed for {bits!r}: {result.stderr}")
    out = {}
    for line in result.stdout.splitlines():
        key, _, rest = line.partition("<")
        out[key] = rest[:-1]  # strip trailing '>'
    return out


# ---- port of the firmware's own HID length decoder -------------------------
# From Unleashed lib/lfrfid/protocols/protocol_hid_generic.c,
# protocol_hid_generic_decode_protocol_size(). The decoded field is 44 bits.
# We feed our generated .rfid Data bytes back through this to confirm the
# length prefix we wrote decodes to the length we intended. 0 = "unknown".

HID_DECODED_BIT_SIZE = 44


def fw_get_bit(data_bytes, index):  # MSB-first, matching bit_lib
    return (data_bytes[index // 8] >> (7 - (index % 8))) & 1


def fw_hid_decode_size(data_bytes):
    for bit_index in range(6):
        if fw_get_bit(data_bytes, bit_index):
            return HID_DECODED_BIT_SIZE - bit_index - 1
    if not fw_get_bit(data_bytes, 6):
        return 37
    bit_index = 7
    size = 36
    while not fw_get_bit(data_bytes, bit_index) and size >= 26:
        size -= 1
        bit_index += 1
    return size if size >= 26 else 0


def main():
    random.seed(1234)
    with tempfile.TemporaryDirectory() as tmp:
        driver = os.path.join(tmp, "format_driver")
        sim = os.path.join(tmp, "capture_sim")
        build(driver, [os.path.join(HERE, "format_driver.c"), os.path.join(ROOT, "wiegand_format.c")])
        build(
            sim,
            [
                os.path.join(HERE, "capture_sim.c"),
                os.path.join(ROOT, "wiegand_capture.c"),
                os.path.join(ROOT, "wiegand_format.c"),
            ],
            extra=["-I", os.path.join(HERE, "shim")],
        )
        rfid = os.path.join(tmp, "rfid_driver")
        build(rfid, [os.path.join(HERE, "rfid_driver.c"), os.path.join(ROOT, "wiegand_rfid.c")])

        # 1. Raw views, every length 1..128, several random patterns each,
        #    plus all-zeros and all-ones.
        for n in range(1, 129):
            patterns = ["0" * n, "1" * n] + [
                "".join(random.choice("01") for _ in range(n)) for _ in range(4)
            ]
            for bits in patterns:
                f = run_driver(driver, bits)
                check(f"plain n={n}", f["PLAIN"], bits)
                check(f"grouped n={n}", f["GROUPED"], ref_grouped(bits))
                check(f"hex right n={n}", f["HEXR"], ref_hex_right(bits))
                check(f"hex left n={n}", f["HEXL"], ref_hex_left(bits))
                # The grouped view must be the same bits once separators go.
                check(f"grouped bits n={n}", f["GROUPED"].replace(" ", "").replace("\n", ""), bits)

        # 2. 26-bit H10301, corner values and a few ordinary ones.
        for fc, cn in [(0, 0), (255, 65535), (159, 6052), (1, 1), (123, 4567), (200, 32768)]:
            bits = h10301(fc, cn)
            want = f"If H10301 (26):\nFC {fc}  CN {cn}\nEven parity: OK\nOdd parity: OK"
            check(f"H10301 {fc}/{cn}", run_driver(driver, bits)["DECODE"], want)
            # One flipped data bit in each half must trip that half's parity.
            bad = run_driver(driver, flip(bits, 3))["DECODE"]
            check(f"H10301 {fc}/{cn} even err", bad.endswith("Even parity: ERROR\nOdd parity: OK"), True)
            bad = run_driver(driver, flip(bits, 20))["DECODE"]
            check(f"H10301 {fc}/{cn} odd err", bad.endswith("Even parity: OK\nOdd parity: ERROR"), True)

        # 3. 34-bit H10306.
        for fc, cn in [(0, 0), (65535, 65535), (4321, 54321), (1, 2)]:
            bits = h10306(fc, cn)
            want = f"If H10306 (34):\nFC {fc}  CN {cn}\nEven parity: OK\nOdd parity: OK"
            check(f"H10306 {fc}/{cn}", run_driver(driver, bits)["DECODE"], want)
            bad = run_driver(driver, flip(bits, 5))["DECODE"]
            check(f"H10306 {fc}/{cn} even err", bad.endswith("Even parity: ERROR\nOdd parity: OK"), True)
            bad = run_driver(driver, flip(bits, 30))["DECODE"]
            check(f"H10306 {fc}/{cn} odd err", bad.endswith("Even parity: OK\nOdd parity: ERROR"), True)

        # 4. 37-bit: H10304 fields, and the same bits read as H10302.
        for fc, cn in [(0, 0), (65535, 524287), (1234, 123456), (1, 1)]:
            bits = h10304(fc, cn)
            cn35 = int(bits[1:36], 2)
            want = (
                f"If H10304 (37):\nFC {fc}  CN {cn}\nIf H10302 (37):\nCN {cn35}"
                "\nEven parity: OK\nOdd parity: OK"
            )
            check(f"H10304 {fc}/{cn}", run_driver(driver, bits)["DECODE"], want)
            bad = run_driver(driver, flip(bits, 4))["DECODE"]
            check(f"H10304 {fc}/{cn} even err", bad.endswith("Even parity: ERROR\nOdd parity: OK"), True)
            bad = run_driver(driver, flip(bits, 30))["DECODE"]
            check(f"H10304 {fc}/{cn} odd err", bad.endswith("Even parity: OK\nOdd parity: ERROR"), True)
            # Bit 19 (index 18) is covered by BOTH parities.
            bad = run_driver(driver, flip(bits, 18))["DECODE"]
            check(f"H10304 {fc}/{cn} shared", bad.endswith("Even parity: ERROR\nOdd parity: ERROR"), True)

        # 5. 24-bit has no parity: fields only.
        for _ in range(20):
            bits = "".join(random.choice("01") for _ in range(24))
            want = f"If 24-bit FC/CN:\nFC {int(bits[0:8], 2)}  CN {int(bits[8:24], 2)}"
            check("24-bit", run_driver(driver, bits)["DECODE"], want)

        # 5a. 36-bit Keyscan C15001.
        for oem, fc, cn in [(0, 0, 0), (1023, 255, 65535), (512, 77, 31000), (1, 1, 1)]:
            bits = keyscan36(oem, fc, cn)
            want = (
                f"If Keyscan C15001:\nOEM {oem}  FC {fc}\nCN {cn}"
                "\nEven parity: OK\nOdd parity: OK"
            )
            check(f"C15001 {oem}/{fc}/{cn}", run_driver(driver, bits)["DECODE"], want)
            bad = run_driver(driver, flip(bits, 6))["DECODE"]
            check("C15001 even err", bad.endswith("Even parity: ERROR\nOdd parity: OK"), True)
            bad = run_driver(driver, flip(bits, 25))["DECODE"]
            check("C15001 odd err", bad.endswith("Even parity: OK\nOdd parity: ERROR"), True)

        # 5b. Corporate 1000, 35-bit and 48-bit, with all three parity bits.
        ok3 = "\nEven parity: OK\nOdd parity: OK\nOverall parity: OK"
        cases35 = [(0, 0), (4095, 1048575), (2222, 777777), (1, 1)]
        cases35 += [(random.randrange(4096), random.randrange(1 << 20)) for _ in range(20)]
        for cc, cn in cases35:
            bits = corp1000_35(cc, cn)
            want = f"If Corp 1000 (35):\nCC {cc}  CN {cn}" + ok3
            check(f"C1k35 {cc}/{cn}", run_driver(driver, bits)["DECODE"], want)
            # Any single flipped bit must break the overall parity at least.
            for index in random.sample(range(35), 6):
                bad = run_driver(driver, flip(bits, index))["DECODE"]
                check(f"C1k35 flip {index}", "ERROR" in bad, True)
        cases48 = [(0, 0), (4194303, 8388607), (4200, 120646), (1, 1)]
        cases48 += [(random.randrange(1 << 22), random.randrange(1 << 23)) for _ in range(20)]
        for cc, cn in cases48:
            bits = corp1000_48(cc, cn)
            want = f"If Corp 1000 (48):\nCC {cc}  CN {cn}" + ok3
            check(f"C1k48 {cc}/{cn}", run_driver(driver, bits)["DECODE"], want)
            for index in random.sample(range(48), 6):
                bad = run_driver(driver, flip(bits, index))["DECODE"]
                check(f"C1k48 flip {index}", "ERROR" in bad, True)

        # 5c. A real capture: the sample file from the original app is a
        #     48-bit Corporate 1000 read. Its three parity bits must check out.
        with open(os.path.join(ROOT, "examples", "C1.wgn")) as sample:
            raw = [l for l in sample if l.startswith("RAW_Data: ")][0].split()[1:]
        real = "".join(token[1] for token in raw if token.startswith("D"))
        check("C1.wgn length", len(real), 48)
        check(
            "C1.wgn decode",
            run_driver(driver, real)["DECODE"],
            "If Corp 1000 (48):\nCC 4200  CN 120646" + ok3,
        )
        check("C1.wgn hex", run_driver(driver, real)["HEXR"], "00106803AE8D")

        # 6. Keypad bursts.
        check("key 4-bit 5", run_driver(driver, "0101")["DECODE"], "Keypad 4-bit\nKey: 5")
        check("key 4-bit *", run_driver(driver, "1010")["DECODE"], "Keypad 4-bit\nKey: * / ESC (10)")
        check("key 4-bit #", run_driver(driver, "1011")["DECODE"], "Keypad 4-bit\nKey: # / ENT (11)")
        check("key 8-bit 7", run_driver(driver, "10000111")["DECODE"], "Keypad 8-bit: check OK\nKey: 7")
        check(
            "key 8-bit bad",
            run_driver(driver, "10010111")["DECODE"],
            "Keypad 8-bit: check ERROR\nKey: 7",
        )

        # 7. Lengths with no decode say nothing rather than guess.
        for n in (1, 2, 3, 25, 27, 33, 40, 56, 64, 100, 128):
            check(f"no decode n={n}", run_driver(driver, "1" * n)["DECODE"], "")

        # 8. "Odd length" flag: common lengths are known, neighbours are not.
        for n, known in [(26, "1"), (25, "0"), (27, "0"), (33, "0"), (37, "1"), (48, "1"), (56, "1"), (64, "1"), (65, "0")]:
            check(f"known n={n}", run_driver(driver, "0" * n)["KNOWN"], known)

        print(f"format tests: {checks} checks, {failures} failures")

        # ---- .rfid export ----------------------------------------------------
        # 10. Key type selection.
        check("rfid keytype 26", run_rfid(rfid, "0" * 26).get("KEYTYPE"), "H10301")
        for n in range(27, 44):
            check(f"rfid keytype {n}", run_rfid(rfid, "0" * n).get("KEYTYPE"), "HIDProx")
        for n in (4, 8, 24, 25, 44, 48, 56, 64):
            r = run_rfid(rfid, "1" * n)
            check(f"rfid unsupported {n}", "UNSUPPORTED" in r, True)

        # 11. H10301 (26-bit): Data bytes are [FC, CN hi, CN lo], and must match
        #     the facility code and card number the credential actually carries.
        for fc, cn in [(0, 0), (255, 65535), (159, 6052), (123, 4567), (200, 32768)]:
            bits = h10301(fc, cn)
            data = run_rfid(rfid, bits)
            check(f"rfid h10301 len {fc}/{cn}", data.get("LEN"), "3")
            check(
                f"rfid h10301 data {fc}/{cn}",
                data.get("DATA"),
                f"{fc:02X} {(cn >> 8) & 0xFF:02X} {cn & 0xFF:02X}",
            )

        # 12. Generic HIDProx (27..43): feed the Data bytes back through the
        #     firmware's own length decoder. It must report the length we wrote,
        #     and the embedded frame bits must equal the input, for many
        #     patterns at every length. This is the check that the length prefix
        #     is right.
        for n in range(27, 44):
            patterns = ["0" * n, "1" * n] + [
                "".join(random.choice("01") for _ in range(n)) for _ in range(8)
            ]
            for bits in patterns:
                data = run_rfid(rfid, bits)
                check(f"rfid hidprox len {n}", data.get("LEN"), "6")
                raw = bytes(int(b, 16) for b in data["DATA"].split())
                check(f"rfid hidprox size {n} {bits[:8]}", fw_hid_decode_size(raw), n)
                # The frame sits in bits (44-n)..43, MSB-first.
                start = HID_DECODED_BIT_SIZE - n
                recovered = "".join(str(fw_get_bit(raw, start + i)) for i in range(n))
                check(f"rfid hidprox bits {n} {bits[:8]}", recovered, bits)
                # Nothing is set above the length prefix region we expect.
                check(
                    f"rfid hidprox clean {n} {bits[:8]}",
                    all(fw_get_bit(raw, i) == 0 for i in range(0, 6)) if n <= 37 else True,
                    True,
                )

        print(f"rfid tests: {checks} checks, {failures} failures (cumulative)")

        # 9. Capture simulation.
        result = subprocess.run([sim], capture_output=True, text=True)
        print(result.stdout.strip())
        if result.stderr.strip():
            print(result.stderr.strip())
        sim_failed = result.returncode != 0

    if failures or sim_failed:
        print("RESULT: FAIL")
        return 1
    print("RESULT: PASS")
    return 0


if __name__ == "__main__":
    sys.exit(main())
